1	import { Block } from "@prototyp/skeletor";
2	import {
3	  EventSendState_Tags,
4	  type EventTimelineItem,
5	} from "@unomed/react-native-matrix-sdk";
6	import type { FC } from "react";
7	import { Image, StyleSheet } from "react-native";
8	import { Colors } from "shared/styles";
9	
10	interface Props {
11	  event: EventTimelineItem;
12	}
13	
14	export const DeliveryStatus: FC<Props> = ({ event }) => {
15	  if (!event.isOwn) return null;
16	
17	  const state = event.localSendState;
18	
19	  if (state?.tag === EventSendState_Tags.SendingFailed) {
20	    return (
21	      <Block
22	        background="transparent"
23	        border={{ borderRadius: 24, borderWidth: 1, borderColor: Colors.error }}
24	        width={18}
25	        height={18}
26	        justify="center"
27	        align="center"
28	      >
29	        <Image
30	          source={require("assets/icons/close.png")}
31	          style={styles.icon}
32	          tintColor={Colors.error}
33	        />
34	      </Block>
35	    );
36	  }
37	
38	  // NotSentYet or Sent — in-flight
39	  if (state) {
40	    return (
41	      <Block
42	        background="transparent"
43	        border={{
44	          borderRadius: 24,
45	          borderWidth: 1,
46	          borderColor: Colors.white20,
47	        }}
48	        width={18}
49	        height={18}
50	      />
51	    );
52	  }
53	
54	  // localSendState undefined — fully confirmed
55	  return (
56	    <Block
57	      background={Colors.white20}
58	      border={{ borderRadius: 24 }}
59	      width={18}
60	      height={18}
61	      justify="center"
62	      align="center"
