import { Block, Text } from "@prototyp/skeletor";
import type { FC } from "react";
import { Image, type ImageSourcePropType, StyleSheet } from "react-native";
import { Button } from "shared/components";
import { Colors } from "shared/styles";

type Props = {
  title: string;
  icon: ImageSourcePropType;
  hasSeparator?: boolean;
  tintColor?: string;
  textColor?: string;
  onPress: () => void;
};

export const MessageContentListItem: FC<Props> = ({
  title,
  icon,
  hasSeparator = true,
  tintColor = Colors.white50,
  textColor = Colors.white,
  onPress,
}) => {
  return (
    <Button.Wrapper onPress={onPress}>
      <Block
        flexDirection="row"
        align="center"
        gap={12}
        paddings={[20, 0]}
        border={
          hasSeparator
            ? { borderBottomWidth: 1, borderColor: Colors.white5 }
            : undefined
        }
      >
        <Image
          source={icon}
          width={24}
          height={24}
          style={styles.icon}
          tintColor={tintColor}
        />
        <Text color={textColor}>{title}</Text>
      </Block>
    </Button.Wrapper>
  );
};

const styles = StyleSheet.create({
  icon: {
    width: 24,
    height: 24,
  },
});

