575	  public static getTopReactions = (
576	    event: EventTimelineItem,
577	    limit = 3,
578	  ): TimelineReaction[] => {
579	    const normalized = this.getNormalizedReactions(event);
580	    return normalized
581	      .sort(
582	        (a, b) => b.count - a.count || b.latestTimestamp - a.latestTimestamp,
583	      )
584	      .slice(0, limit);
585	  };
586	
587	  private static getNormalizedReactions = (
588	    event: EventTimelineItem,
589	  ): TimelineReaction[] => {
590	    const reactionCandidates: unknown[] = [
591	      this.readValue(event, ["reactions"]),
592	      this.readValue(event, ["properties", "reactions"]),
593	      this.readValue(event, ["content", "inner", "reactions"]),
594	      this.readValue(event, ["content", "inner", "content", "reactions"]),
595	      this.readValue(event, [
596	        "content",
597	        "inner",
598	        "content",
599	        "kind",
600	        "inner",
601	        "content",
602	        "reactions",
603	      ]),
604	    ].filter(Boolean);
605	
606	    for (const candidate of reactionCandidates) {
607	      const parsed = this.parseReactionsCandidate(candidate);
608	      if (parsed.length) return parsed;
609	    }
610	
611	    return [];
612	  };
613	
614	  private static parseReactionsCandidate = (
615	    candidate: unknown,
616	  ): TimelineReaction[] => {
617	    if (!candidate) return [];
618	
619	    if (Array.isArray(candidate)) {
620	      return candidate
621	        .map((reaction) => this.parseSingleReaction(reaction))
622	        .filter((reaction): reaction is TimelineReaction => Boolean(reaction));
623	    }
624	
625	    if (candidate instanceof Map) {
626	      return Array.from(candidate.entries())
627	        .map(([key, value]) => this.parseEntryReaction(key, value))
628	        .filter((reaction): reaction is TimelineReaction => Boolean(reaction));
629	    }
630	
631	    if (typeof candidate === "object") {
632	      return Object.entries(candidate as Record<string, unknown>)
633	        .map(([key, value]) => this.parseEntryReaction(key, value))
634	        .filter((reaction): reaction is TimelineReaction => Boolean(reaction));
635	    }
636	
637	    return [];
638	  };
639	
640	  private static parseEntryReaction = (
641	    key: string,
642	    rawValue: unknown,
643	  ): TimelineReaction | null => {
644	    const currentUserId = MatrixCore.instance?.userId() ?? "";
645	    const normalizedKey = this.normalizeReactionKey(key);
646	    if (!normalizedKey) return null;
647	
648	    const detailedReaction = this.parseSingleReaction(rawValue);
649	    if (detailedReaction) {
650	      return {
651	        ...detailedReaction,
652	        key: normalizedKey,
653	        displayKey: String(detailedReaction.displayKey || normalizedKey).slice(
654	          0,
655	          16,
656	        ),
657	      };
658	    }
659	
660	    const senders = this.toSenders(rawValue, currentUserId);
661	    return {
662	      key: normalizedKey,
663	      displayKey: normalizedKey.slice(0, 16),
664	      count: senders.count,
665	      latestTimestamp: senders.latestTimestamp,
666	      isHighlighted: senders.isHighlighted,
667	      senders: senders.senders,
668	    };
669	  };
670	
671	  private static parseSingleReaction = (
672	    rawReaction: unknown,
673	  ): TimelineReaction | null => {
674	    if (!rawReaction || typeof rawReaction !== "object") return null;
675	    const currentUserId = MatrixCore.instance?.userId() ?? "";
676	
677	    const reaction = rawReaction as Record<string, unknown>;
678	    const normalizedKey = this.normalizeReactionKey(
679	      reaction.key ??
680	        reaction.displayKey ??
681	        reaction.emoji ??
682	        reaction.reaction,
683	    );
684	    if (!normalizedKey) return null;
685	
686	    const senders = this.toSenders(reaction.senders, currentUserId);
687	    const rawCount = Number(reaction.count);
688	    const count =
689	      Number.isFinite(rawCount) && rawCount > 0 ? rawCount : senders.count;
690	
691	    return {
692	      key: normalizedKey,
693	      displayKey: String(reaction.displayKey ?? normalizedKey).slice(0, 16),
694	      count,
695	      latestTimestamp: senders.latestTimestamp,
696	      isHighlighted:
697	        Boolean(reaction.isHighlighted) ||
698	        Boolean(reaction.highlighted) ||
699	        senders.isHighlighted,
700	      senders: senders.senders,
701	    };
702	  };
703	
704	  private static toSenders = (
705	    rawSenders: unknown,
706	    currentUserId: string,
707	  ): {
708	    count: number;
709	    latestTimestamp: number;
710	    isHighlighted: boolean;
711	    senders: TimelineReactionSender[];
712	  } => {
713	    if (!rawSenders)
714	      return {
715	        count: 1,
716	        latestTimestamp: 0,
717	        isHighlighted: false,
718	        senders: [],
719	      };
720	
721	    if (Array.isArray(rawSenders)) {
722	      const senders: TimelineReactionSender[] = rawSenders
723	        .map((sender) => ({
724	          userId: this.extractSenderUserId(sender),
725	          timestamp: this.extractTimestamp(sender),
726	        }))
727	        .filter((s) => s.userId);
728	      const latestTimestamp = senders.reduce(
729	        (max, s) => Math.max(max, s.timestamp),
730	        0,
731	      );
732	      const isHighlighted = senders.some((s) => s.userId === currentUserId);
733	      return {
734	        count: rawSenders.length || 1,
735	        latestTimestamp,
736	        isHighlighted,
737	        senders,
738	      };
739	    }
740	
741	    if (rawSenders instanceof Map) {
742	      const entries = Array.from(rawSenders.entries());
743	      const senders: TimelineReactionSender[] = entries
744	        .map(([senderId, sender]) => ({
745	          userId:
746	            typeof senderId === "string" && senderId
747	              ? senderId
748	              : this.extractSenderUserId(sender),
749	          timestamp: this.extractTimestamp(sender),
750	        }))
751	        .filter((s) => s.userId);
752	      const latestTimestamp = senders.reduce(
753	        (max, s) => Math.max(max, s.timestamp),
754	        0,
755	      );
756	      const isHighlighted = senders.some((s) => s.userId === currentUserId);
757	      return {
758	        count: entries.length || 1,
759	        latestTimestamp,
760	        isHighlighted,
761	        senders,
762	      };
763	    }
764	
765	    if (typeof rawSenders === "object") {
766	      const entries = Object.entries(rawSenders as Record<string, unknown>);
767	      const senders: TimelineReactionSender[] = entries
768	        .map(([senderId, sender]) => ({
769	          userId: senderId || this.extractSenderUserId(sender),
770	          timestamp: this.extractTimestamp(sender),
771	        }))
772	        .filter((s) => s.userId);
773	      const latestTimestamp = senders.reduce(
774	        (max, s) => Math.max(max, s.timestamp),
775	        0,
776	      );
777	      const isHighlighted = senders.some((s) => s.userId === currentUserId);
778	      return {
779	        count: entries.length || 1,
780	        latestTimestamp,
781	        isHighlighted,
782	        senders,
783	      };
784	    }
785	
786	    return { count: 1, latestTimestamp: 0, isHighlighted: false, senders: [] };
787	  };
788	
789	  private static extractTimestamp = (sender: unknown): number => {
790	    if (!sender || typeof sender !== "object") return 0;
791	    const record = sender as Record<string, unknown>;
792	    const rawTimestamp =
793	      record.timestamp ??
794	      record.ts ??
795	      this.readValue(record, ["inner", "timestamp"]);
796	    const timestamp = Number(rawTimestamp);
797	    return Number.isFinite(timestamp) ? timestamp : 0;
798	  };
799	
800	  private static extractSenderUserId = (sender: unknown): string => {
801	    if (!sender || typeof sender !== "object") return "";
802	    const record = sender as Record<string, unknown>;
803	    const rawUserId =
804	      record.userId ??
805	      record.senderId ??
806	      record.id ??
807	      this.readValue(record, ["inner", "userId"]);
808	    return typeof rawUserId === "string" ? rawUserId : "";
809	  };
810	
811	  private static normalizeReactionKey = (rawKey: unknown): string => {
812	    if (typeof rawKey !== "string") return "";
813	    return rawKey.trim();
814	  };
815	
816	  private static readValue = (source: unknown, path: string[]): unknown => {
817	    if (!source || typeof source !== "object") return undefined;
818	    let current: unknown = source;
819	    for (const segment of path) {
820	      if (!current || typeof current !== "object") return undefined;
821	      current = (current as Record<string, unknown>)[segment];
822	    }
823	    if (typeof current === "function") {
824	      try {
825	        return (current as () => unknown)();
826	      } catch {
827	        return undefined;
828	      }
829	    }
830	    return current;
831	  };
832	}
