26	  type NativeSyntheticEvent,
27	  StyleSheet,
28	} from "react-native";
29	import { MemberDetailsBottomSheet, SeenByBottomSheet } from "shared/components";
30	import { useMemberDetails } from "shared/hooks";
31	import { DateDivider } from "../date-divider";
32	import { FailedEchoBottomSheet } from "../failed-echo-bottom-sheet";
33	import { GroupedInfoMessages } from "../grouped-info-messages";
34	import { MessageContentBottomSheet } from "../message-content-bottom-sheet";
35	import { NewMessagesButton } from "../new-messages-button";
36	import { ReactionsBottomSheet } from "../reactions-bottom-sheet";
37	import { RoomIdentityBanner } from "../room-identity-banner";
38	import { RoomInput } from "../room-input";
39	import { ScrollToBottomButton } from "../scroll-to-bottom-button";
40	import { ShieldModal } from "../shield-modal";
41	import { SingleMessageType } from "../single-message-type";
42	
43	interface Props {
44	  room: RoomInterface;
45	  roomId: string;
46	}
47	
48	export const RoomTimeline: FC<Props> = ({ room, roomId }) => {
49	  const flashListRef = useRef<FlashListRef<TimelineListItem>>(null);
50	  const isAtBottomRef = useRef(true);
51	  const suppressScrollDownRef = useRef(false);
52	  const lastEventKeyRef = useRef<string | undefined>(undefined);
53	  const visibleHeightRef = useRef(0);
54	  const [showNewMessageArrived, setShowNewMessageArrived] = useState(false);
55	  const [showScrollDown, setShowScrollDown] = useState(false);
56	  const {
57	    events,
58	    isPaginatingRef,
59	    reachedStartRef,
60	    isDirect,
61	    loadMoreMessages,
62	    markAsRead,
63	  } = useRoomTimeline({
64	    room,
65	    roomId,
66	  });
67	  const [scrollToEventId, setScrollToEventId] = useAtom(
68	    TimelineAtoms.scrollToEventId,
69	  );
70	  const [seenByUsers, setSeenByUsers] = useAtom(TimelineAtoms.seenByUsers);
71	  const [reactionsPayload, setReactionsPayload] = useAtom(
72	    TimelineAtoms.reactionsPayload,
73	  );
74	  const [shieldPayload, setShieldPayload] = useAtom(
75	    TimelineAtoms.shieldPayload,
76	  );
77	  const { isPinViolatingUsersLoading, violatingUsers, pinViolatingUsers } =
78	    useRoomIdentityViolations(room);
79	  const {
80	    selectedMember,
81	    isBottomSheetOpen,
82	    openMemberDetails,
83	    closeMemberDetails,
84	  } = useMemberDetails();
85	
86	  const sortedEvents = useMemo(() => {
87	    const sorted = [...events].sort(
88	      (a, b) => Number(a.timestamp) - Number(b.timestamp),
89	    );
90	
91	    return filterSameStateKey(sorted);
92	  }, [events]);
93	
94	  const eventsWithDividers = useMemo(() => {
95	    const items = groupInfoEvents(addDateDividers(sortedEvents));
96	
97	    // Pre-compute isPreviousSameSender so it's not recalculated per-item during render
98	    let prevSender: string | null = null;
99	    for (const item of items) {
100	      if (item.type !== "event") {
101	        prevSender = null;
102	        continue;
103	      }
104	      const isMsgLike =
105	        item.data.content.tag === TimelineItemContent_Tags.MsgLike;
106	      if (!isMsgLike) {
107	        prevSender = null;
108	        continue;
109	      }
110	      item.isPreviousSameSender =
111	        isDirect || (prevSender !== null && prevSender === item.data.sender);
112	      prevSender = item.data.sender;
113	    }
114	
115	    return items;
116	  }, [sortedEvents, isDirect]);
117	
118	  // Reverse for inverted FlashList: [newest, ..., oldest]
119	  const reversedEvents = useMemo(
120	    () => [...eventsWithDividers].reverse(),
121	    [eventsWithDividers],
122	  );
123	
124	  const handleScrollToEvent = useCallback(
125	    (eventId: string) => {
126	      const index = reversedEvents.findIndex(
127	        (item) => item.type === "event" && getEventId(item.data) === eventId,
128	      );
129	      if (index === -1) return;
130	
131	      flashListRef.current?.scrollToIndex({
132	        index,
133	        animated: true,
134	        viewPosition: 0.5,
135	      });
136	    },
137	    [reversedEvents],
138	  );
139	
140	  useEffect(() => {
141	    if (!scrollToEventId) return;
142	    handleScrollToEvent(scrollToEventId);
143	    setScrollToEventId(null);
144	  }, [scrollToEventId, handleScrollToEvent, setScrollToEventId]);
145	
146	  const handleScrollDown = useCallback(() => {
147	    // In inverted list, offset 0 is the visual bottom (newest messages)
148	    suppressScrollDownRef.current = true;
149	    flashListRef.current?.scrollToOffset({ offset: 0, animated: true });
150	    setShowNewMessageArrived(false);
151	    setShowScrollDown(false);
152	  }, []);
153	
154	  const handleOnScroll = useCallback(
155	    ({ nativeEvent }: NativeSyntheticEvent<NativeScrollEvent>) => {
156	      const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
157	      visibleHeightRef.current = layoutMeasurement.height;
158	
159	      // Inverted list: large contentOffset.y = near oldest messages (visual top)
160	      // Paginate when within 2x visible height of the oldest content
161	      const distanceFromTop =
162	        contentSize.height - contentOffset.y - layoutMeasurement.height;
163	      const nearTop = distanceFromTop < layoutMeasurement.height * 2;
164	      if (nearTop && !isPaginatingRef.current && !reachedStartRef.current) {
165	        loadMoreMessages();
166	      }
167	
168	      // Inverted list: contentOffset.y near 0 = at visual bottom (newest messages)
169	      const paddingToBottom = 100;
170	      const atBottom = contentOffset.y <= paddingToBottom;
171	      isAtBottomRef.current = atBottom;
172	
173	      if (!suppressScrollDownRef.current) setShowScrollDown(!atBottom);
174	
175	      if (!atBottom) return;
176	      suppressScrollDownRef.current = false;
177	      setShowNewMessageArrived(false);
178	      markAsRead();
179	    },
180	    [loadMoreMessages, markAsRead],
181	  );
182	
183	  const handleContentSizeChange = useCallback(
184	    (_w: number, contentHeight: number) => {
185	      // Auto-paginate if content doesn't fill the viewport (initial fill)
186	      if (
187	        contentHeight > 0 &&
188	        visibleHeightRef.current > 0 &&
189	        contentHeight < visibleHeightRef.current &&
190	        !isPaginatingRef.current &&
191	        !reachedStartRef.current
192	      ) {
193	        loadMoreMessages();
194	      }
195	    },
